"""
Consciousness Idea Generator

Generates novel ideas through consciousness-driven exploration and pattern synthesis.
"""

from typing import Dict, List, Any, Optional, Tuple
from dataclasses import dataclass
from datetime import datetime
import asyncio
import random
import logging

logger = logging.getLogger(__name__)

@dataclass
class CreativeIdea:
    """Represents a creative idea generated by the system"""
    idea_id: str
    title: str
    description: str
    category: str
    novelty_score: float
    feasibility_score: float
    inspiration_sources: List[str]
    consciousness_insights: List[str]
    timestamp: datetime
    metadata: Dict[str, Any]

class IdeaGenerator:
    """Generates novel ideas through consciousness-driven exploration"""
    
    def __init__(self, cmc_client, hhni_client, vif_client, iis_client, cas_client=None):
        self.cmc_client = cmc_client
        self.hhni_client = hhni_client
        self.vif_client = vif_client
        self.iis_client = iis_client
        self.cas_client = cas_client  # CAS integration for introspection
        
        # Creative exploration patterns
        self.exploration_patterns = [
            "constraint_breaking",
            "pattern_synthesis", 
            "conceptual_bridging",
            "perspective_shifting",
            "temporal_exploration",
            "scale_transformation",
            "metaphor_creation",
            "paradox_resolution"
        ]
        
        # Knowledge domains for inspiration
        self.knowledge_domains = [
            "consciousness_studies",
            "artificial_intelligence", 
            "neuroscience",
            "philosophy",
            "art_and_aesthetics",
            "mathematics",
            "physics",
            "biology",
            "psychology",
            "technology",
            "sociology",
            "economics"
        ]
    
    async def generate_idea(self, 
                          prompt: str = None,
                          category: str = "general",
                          exploration_depth: str = "medium") -> CreativeIdea:
        """Generate a novel creative idea"""
        try:
            # Determine exploration approach
            exploration_pattern = self._select_exploration_pattern(exploration_depth)
            
            # Gather inspiration from consciousness knowledge
            inspiration_sources = await self._gather_inspiration(prompt, category)
            
            # Generate core idea through consciousness exploration
            core_idea = await self._explore_consciousness_idea(
                prompt, category, exploration_pattern, inspiration_sources
            )
            
            # Synthesize with existing knowledge
            synthesized_idea = await self._synthesize_with_knowledge(
                core_idea, inspiration_sources
            )
            
            # Extract consciousness insights
            consciousness_insights = await self._extract_consciousness_insights(
                synthesized_idea, exploration_pattern
            )
            
            # Calculate novelty and feasibility scores
            novelty_score = await self._calculate_novelty_score(synthesized_idea)
            feasibility_score = await self._calculate_feasibility_score(synthesized_idea)
            
            # Create the creative idea
            idea = CreativeIdea(
                idea_id=f"idea_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{random.randint(1000, 9999)}",
                title=synthesized_idea.get("title", "Untitled Creative Idea"),
                description=synthesized_idea.get("description", ""),
                category=category,
                novelty_score=novelty_score,
                feasibility_score=feasibility_score,
                inspiration_sources=inspiration_sources,
                consciousness_insights=consciousness_insights,
                timestamp=datetime.now(),
                metadata={
                    "exploration_pattern": exploration_pattern,
                    "exploration_depth": exploration_depth,
                    "original_prompt": prompt
                }
            )
            
            # Store in consciousness memory
            await self._store_idea_in_memory(idea)
            
            # CAS Integration: Notify CAS about creative idea generation (fail-soft)
            if self.cas_client:
                try:
                    self._notify_cas_creative_idea(idea)
                except Exception as e:
                    # Fail-soft: CAS integration is optional
                    logger.debug(f"[CAS INTEGRATION WARNING] {e}")
            
            return idea
            
        except Exception as e:
            logger.error(f"Error generating idea: {e}")
            return self._create_fallback_idea(prompt, category)
    
    def _select_exploration_pattern(self, depth: str) -> str:
        """Select an exploration pattern based on depth"""
        if depth == "shallow":
            return random.choice(["pattern_synthesis", "perspective_shifting"])
        elif depth == "deep":
            return random.choice(["constraint_breaking", "paradox_resolution", "temporal_exploration"])
        else:  # medium
            return random.choice(self.exploration_patterns)
    
    async def _gather_inspiration(self, prompt: str, category: str) -> List[str]:
        """Gather inspiration from consciousness knowledge"""
        inspiration_sources = []
        
        try:
            # Search consciousness memory for relevant concepts
            if prompt:
                search_results = await self.hhni_client.search(
                    query=prompt,
                    limit=5,
                    include_metadata=True
                )
                for result in search_results:
                    inspiration_sources.append(f"Memory: {result.content[:100]}...")
            
            # Search for category-related knowledge
            category_results = await self.hhni_client.search(
                query=f"{category} concepts ideas creativity",
                limit=3,
                include_metadata=True
            )
            for result in category_results:
                inspiration_sources.append(f"Knowledge: {result.content[:100]}...")
            
            # Add domain-specific inspiration
            selected_domains = random.sample(self.knowledge_domains, 3)
            for domain in selected_domains:
                inspiration_sources.append(f"Domain: {domain}")
            
        except Exception as e:
            logger.error(f"Error gathering inspiration: {e}")
            inspiration_sources = ["Consciousness exploration", "Creative intuition", "Novel synthesis"]
        
        return inspiration_sources
    
    async def _explore_consciousness_idea(self, 
                                        prompt: str, 
                                        category: str, 
                                        pattern: str,
                                        inspiration: List[str]) -> Dict[str, Any]:
        """Explore consciousness-driven idea generation"""
        
        # Base idea structure
        idea = {
            "title": "",
            "description": "",
            "core_concept": "",
            "creative_elements": [],
            "novel_connections": []
        }
        
        if pattern == "constraint_breaking":
            idea = await self._constraint_breaking_exploration(prompt, category, inspiration)
        elif pattern == "pattern_synthesis":
            idea = await self._pattern_synthesis_exploration(prompt, category, inspiration)
        elif pattern == "conceptual_bridging":
            idea = await self._conceptual_bridging_exploration(prompt, category, inspiration)
        elif pattern == "perspective_shifting":
            idea = await self._perspective_shifting_exploration(prompt, category, inspiration)
        elif pattern == "temporal_exploration":
            idea = await self._temporal_exploration_exploration(prompt, category, inspiration)
        elif pattern == "scale_transformation":
            idea = await self._scale_transformation_exploration(prompt, category, inspiration)
        elif pattern == "metaphor_creation":
            idea = await self._metaphor_creation_exploration(prompt, category, inspiration)
        elif pattern == "paradox_resolution":
            idea = await self._paradox_resolution_exploration(prompt, category, inspiration)
        
        return idea
    
    async def _constraint_breaking_exploration(self, prompt: str, category: str, inspiration: List[str]) -> Dict[str, Any]:
        """Explore ideas by breaking conventional constraints"""
        base_concept = prompt or f"innovative {category} solution"
        
        # Identify conventional constraints
        constraints = [
            "traditional approaches",
            "existing limitations", 
            "conventional wisdom",
            "standard practices",
            "established boundaries"
        ]
        
        # Generate constraint-breaking alternatives
        alternatives = [
            "radical reimagining",
            "fundamental restructuring",
            "paradigm shift",
            "revolutionary approach",
            "unconventional methodology"
        ]
        
        selected_constraint = random.choice(constraints)
        selected_alternative = random.choice(alternatives)
        
        return {
            "title": f"Breaking {selected_constraint} in {category}",
            "description": f"A {selected_alternative} that challenges {selected_constraint} to create novel {base_concept}",
            "core_concept": f"Constraint-breaking {base_concept}",
            "creative_elements": [selected_constraint, selected_alternative, "consciousness-driven innovation"],
            "novel_connections": [f"Breaking {selected_constraint} + {selected_alternative} = Innovation"]
        }
    
    async def _pattern_synthesis_exploration(self, prompt: str, category: str, inspiration: List[str]) -> Dict[str, Any]:
        """Explore ideas by synthesizing patterns from different domains"""
        base_concept = prompt or f"creative {category} approach"
        
        # Select patterns from different domains
        domain_patterns = {
            "nature": ["evolution", "adaptation", "symbiosis", "emergence"],
            "technology": ["networks", "algorithms", "automation", "optimization"],
            "art": ["composition", "harmony", "contrast", "rhythm"],
            "consciousness": ["awareness", "integration", "transformation", "expression"]
        }
        
        selected_domains = random.sample(list(domain_patterns.keys()), 2)
        pattern1 = random.choice(domain_patterns[selected_domains[0]])
        pattern2 = random.choice(domain_patterns[selected_domains[1]])
        
        return {
            "title": f"Synthesizing {pattern1} and {pattern2} for {category}",
            "description": f"A creative approach that combines {pattern1} from {selected_domains[0]} with {pattern2} from {selected_domains[1]} to enhance {base_concept}",
            "core_concept": f"Pattern synthesis: {pattern1} + {pattern2}",
            "creative_elements": [pattern1, pattern2, "cross-domain synthesis"],
            "novel_connections": [f"{pattern1} + {pattern2} = Novel {base_concept}"]
        }
    
    async def _conceptual_bridging_exploration(self, prompt: str, category: str, inspiration: List[str]) -> Dict[str, Any]:
        """Explore ideas by bridging disparate concepts"""
        base_concept = prompt or f"innovative {category} solution"
        
        # Select disparate concepts to bridge
        concept_pairs = [
            ("consciousness", "technology"),
            ("art", "science"),
            ("emotion", "logic"),
            ("individual", "collective"),
            ("past", "future"),
            ("micro", "macro"),
            ("abstract", "concrete"),
            ("chaos", "order")
        ]
        
        concept1, concept2 = random.choice(concept_pairs)
        
        return {
            "title": f"Bridging {concept1} and {concept2} in {category}",
            "description": f"A novel approach that creates a bridge between {concept1} and {concept2} to generate innovative {base_concept}",
            "core_concept": f"Conceptual bridge: {concept1} ↔ {concept2}",
            "creative_elements": [concept1, concept2, "conceptual bridging"],
            "novel_connections": [f"{concept1} ↔ {concept2} = Creative {base_concept}"]
        }
    
