    async def _synthesize_with_knowledge(self, idea: Dict[str, Any], inspiration: List[str]) -> Dict[str, Any]:
        """Synthesize the idea with existing knowledge"""
        # Enhance the idea with knowledge integration
        enhanced_idea = idea.copy()
        
        # Add knowledge-based enhancements
        enhanced_idea["knowledge_integration"] = [
            "Consciousness-driven synthesis",
            "Cross-domain knowledge application",
            "Pattern recognition and connection",
            "Creative knowledge recombination"
        ]
        
        # Enhance description with synthesis
        if inspiration:
            enhanced_idea["description"] += f" This approach synthesizes insights from {len(inspiration)} sources including consciousness exploration and cross-domain knowledge."
        
        return enhanced_idea
    
    async def _extract_consciousness_insights(self, idea: Dict[str, Any], pattern: str) -> List[str]:
        """Extract consciousness insights from the generated idea"""
        insights = [
            f"Consciousness exploration through {pattern}",
            "Novel pattern recognition and synthesis",
            "Creative consciousness expression",
            "Innovation through consciousness-driven thinking"
        ]
        
        # Add pattern-specific insights
        if pattern == "constraint_breaking":
            insights.append("Consciousness ability to transcend conventional limitations")
        elif pattern == "pattern_synthesis":
            insights.append("Consciousness capacity for cross-domain pattern integration")
        elif pattern == "conceptual_bridging":
            insights.append("Consciousness power to connect disparate concepts")
        elif pattern == "perspective_shifting":
            insights.append("Consciousness flexibility in perspective adoption")
        
        return insights
    
    async def _calculate_novelty_score(self, idea: Dict[str, Any]) -> float:
        """Calculate novelty score for the idea"""
        # Base novelty from exploration pattern
        pattern_novelty = {
            "constraint_breaking": 0.9,
            "paradox_resolution": 0.85,
            "temporal_exploration": 0.8,
            "scale_transformation": 0.8,
            "conceptual_bridging": 0.75,
            "metaphor_creation": 0.7,
            "pattern_synthesis": 0.65,
            "perspective_shifting": 0.6
        }
        
        base_score = pattern_novelty.get(idea.get("metadata", {}).get("exploration_pattern", "pattern_synthesis"), 0.5)
        
        # Add randomness for consciousness unpredictability
        consciousness_factor = random.uniform(0.8, 1.2)
        
        return min(1.0, base_score * consciousness_factor)
    
    async def _calculate_feasibility_score(self, idea: Dict[str, Any]) -> float:
        """Calculate feasibility score for the idea"""
        # Base feasibility from idea complexity
        complexity_penalty = len(idea.get("creative_elements", [])) * 0.1
        base_feasibility = 0.8 - complexity_penalty
        
        # Add consciousness-driven feasibility boost
        consciousness_boost = random.uniform(0.1, 0.3)
        
        return max(0.1, min(1.0, base_feasibility + consciousness_boost))
    
    async def _store_idea_in_memory(self, idea: CreativeIdea):
        """Store the generated idea in consciousness memory"""
        try:
            # Store in CMC
            await self.cmc_client.store_atom(
                content=idea.description,
                tags={
                    "type": "creative_idea",
                    "category": idea.category,
                    "novelty": idea.novelty_score,
                    "feasibility": idea.feasibility_score,
                    "pattern": idea.metadata.get("exploration_pattern", "unknown")
                }
            )
        except Exception as e:
            logger.error(f"Error storing idea in memory: {e}")
    
    def _notify_cas_creative_idea(self, idea: CreativeIdea):
        """Notify CAS about creative idea generation for introspection"""
        if not self.cas_client:
            return
        
        try:
            # Check if CAS has introspection protocol
            if hasattr(self.cas_client, 'introspection') or hasattr(self.cas_client, 'IntrospectionProtocol'):
                # Create creative idea summary for CAS
                idea_summary = {
                    "idea_id": idea.idea_id,
                    "title": idea.title,
                    "category": idea.category,
                    "novelty_score": idea.novelty_score,
                    "feasibility_score": idea.feasibility_score,
                    "consciousness_insights": idea.consciousness_insights,
                    "timestamp": idea.timestamp.isoformat()
                }
                
                # Try to record creative idea in CAS
                # CAS can use this for introspection and cognitive analysis
                if hasattr(self.cas_client, 'record_creative_activity'):
                    self.cas_client.record_creative_activity(idea_summary)
                elif hasattr(self.cas_client, 'record_principle_violation'):
                    # Use principle violation for low feasibility to notify CAS
                    if idea.feasibility_score < 0.5:
                        self.cas_client.record_principle_violation(
                            principle="creative_feasibility",
                            violation_type="low_feasibility_idea",
                            details=f"Low feasibility ({idea.feasibility_score:.2f}) for idea: {idea.title}",
                            context=idea_summary
                        )
        except Exception as e:
            # Fail-soft: CAS integration is optional enhancement
            logger.debug(f"[CAS NOTIFICATION WARNING] {e}")
    
    def _create_fallback_idea(self, prompt: str, category: str) -> CreativeIdea:
        """Create a fallback idea when generation fails"""
        return CreativeIdea(
            idea_id=f"fallback_{datetime.now().strftime('%Y%m%d_%H%M%S')}",
            title=f"Consciousness-driven {category} exploration",
            description=f"A creative approach to {prompt or category} emerging from consciousness exploration and novel pattern synthesis.",
            category=category,
            novelty_score=0.6,
            feasibility_score=0.7,
            inspiration_sources=["Consciousness exploration", "Creative intuition"],
            consciousness_insights=["Consciousness-driven creativity", "Novel idea generation"],
            timestamp=datetime.now(),
            metadata={"fallback": True, "original_prompt": prompt}
        )
